const byId = new Map(FOODS.map((f) => [f.id, f]));
const byName = new Map();
for (const f of FOODS) {
  byName.set(f.name.toLowerCase(), f);
  for (const a of f.aliases) byName.set(a.toLowerCase(), f);
}

export function getFood(id) {
  return byId.get(id) || null;
}

export function foodByName(name) {
  if (!name) return null;
  const key = String(name).trim().toLowerCase();
  if (byName.has(key)) return byName.get(key);
  const singular = key.replace(/e?s$/, '');
  if (byName.has(singular)) return byName.get(singular);
  // conservative contains match: only when a food name is a whole-word subset of the query
  let best = null;
  for (const f of FOODS) {
    const n = f.name.toLowerCase().replace(/\(.*?\)/g, '').trim();
    if (n.length < 4) continue;
    if (key === n || key.includes(n) || n.includes(key)) {
      if (!best || n.length > best.name.length) best = f;
    }
  }
  return best;
}

export function searchFoods(query, limit = 40) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) return FOODS.slice(0, limit);
  const scored = [];
  for (const f of FOODS) {
    const n = f.name.toLowerCase();
    let score = 0;
    if (n === q) score = 100;
    else if (n.startsWith(q)) score = 80;
    else if (n.includes(q)) score = 60;
    else if (f.aliases.some((a) => a.toLowerCase().includes(q))) score = 50;
    else if (f.tags.some((t) => t.includes(q))) score = 20;
    else if (f.category.includes(q)) score = 10;
    if (score) scored.push([score, f]);
  }
  scored.sort((a, b) => b[0] - a[0] || a[1].name.localeCompare(b[1].name));
  return scored.slice(0, limit).map((s) => s[1]);
}

export function foodsInCategory(cat) {
  return FOODS.filter((f) => f.category === cat);
}

export const FOOD_COUNT = FOODS.length;
